import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { teamLogic } from 'scenes/teamLogic'

import { aiConsentLogic } from '~/layout/ai/aiConsentLogic'
import { IntegrationType } from '~/types'

export type TodayPrompt = 'github' | 'ai'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPromptsLogicValues {
    aiAccessRequested: boolean // aiConsentLogic
    dataProcessingAccepted: boolean // aiConsentLogic
    dataProcessingApprovalDisabledReason: string | null // aiConsentLogic
    requestingAiAccess: boolean // aiConsentLogic
    githubIntegrations: IntegrationType[] // integrationsLogic
    integrationsLoading: boolean // integrationsLogic
    currentTeamId: number | null // teamLogic
    aiEnabled: boolean
    aiPromptDismissed: boolean
    canEnableAi: boolean
    dismissedPrompts: Record<string, true>
    githubConnected: boolean
    githubDismissed: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPromptsLogicActions {
    acceptDataProcessing: (
        testOnlyOverride?: boolean | undefined,
        resumeUrl?: string | undefined
    ) => {
        resumeUrl: string | undefined
        testOnlyOverride: boolean | undefined
    } // aiConsentLogic
    requestAiAccess: () => {
        value: true
    } // aiConsentLogic
    dismissPrompt: (prompt: TodayPrompt) => {
        prompt: TodayPrompt
    }
    dismissPromptForTeam: (
        teamId: number | null,
        prompt: TodayPrompt
    ) => {
        prompt: TodayPrompt
        teamId: number | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPromptsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        aiEnabled: (dataProcessingAccepted: boolean) => boolean
        canEnableAi: (dataProcessingApprovalDisabledReason: string | null) => boolean
        githubConnected: (githubIntegrations: IntegrationType[]) => boolean
        githubDismissed: (dismissedPrompts: Record<string, true>, currentTeamId: number | null) => boolean
        aiPromptDismissed: (dismissedPrompts: Record<string, true>, currentTeamId: number | null) => boolean
    }
}

export type todayPromptsLogicType = MakeLogicType<
    todayPromptsLogicValues,
    todayPromptsLogicActions,
    Record<string, any>,
    todayPromptsLogicMeta
>

function promptKey(teamId: number | null, prompt: TodayPrompt): string {
    return `${teamId}:${prompt}`
}

export const todayPromptsLogic = kea<todayPromptsLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayPromptsLogic']),
    connect(() => ({
        values: [
            aiConsentLogic,
            [
                'aiAccessRequested',
                'dataProcessingAccepted',
                'dataProcessingApprovalDisabledReason',
                'requestingAiAccess',
            ],
            integrationsLogic,
            ['githubIntegrations', 'integrationsLoading'],
            teamLogic,
            ['currentTeamId'],
        ],
        actions: [aiConsentLogic, ['acceptDataProcessing', 'requestAiAccess']],
    })),
    actions({
        dismissPrompt: (prompt: TodayPrompt) => ({ prompt }),
        dismissPromptForTeam: (teamId: number | null, prompt: TodayPrompt) => ({ teamId, prompt }),
    }),
    reducers({
        // pinned: localStorage key via the logic path and reducer name, renaming resets users' choice
        dismissedPrompts: [
            {} as Record<string, true>,
            { persist: true },
            {
                dismissPromptForTeam: (state, { teamId, prompt }) => ({ ...state, [promptKey(teamId, prompt)]: true }),
            },
        ],
    }),
    selectors({
        aiEnabled: [
            (s) => [s.dataProcessingAccepted],
            (dataProcessingAccepted: boolean): boolean => dataProcessingAccepted,
        ],
        canEnableAi: [
            (s) => [s.dataProcessingApprovalDisabledReason],
            (dataProcessingApprovalDisabledReason: string | null): boolean => !dataProcessingApprovalDisabledReason,
        ],
        githubConnected: [
            (s) => [s.githubIntegrations],
            (githubIntegrations: IntegrationType[]): boolean => githubIntegrations.length > 0,
        ],
        githubDismissed: [
            (s) => [s.dismissedPrompts, s.currentTeamId],
            (dismissedPrompts: Record<string, true>, currentTeamId: number | null): boolean =>
                !!dismissedPrompts[promptKey(currentTeamId, 'github')],
        ],
        aiPromptDismissed: [
            (s) => [s.dismissedPrompts, s.currentTeamId],
            (dismissedPrompts: Record<string, true>, currentTeamId: number | null): boolean =>
                !!dismissedPrompts[promptKey(currentTeamId, 'ai')],
        ],
    }),
    listeners(({ actions, values }) => ({
        dismissPrompt: ({ prompt }) => {
            // pinned: analytics event name, renaming breaks dashboards
            posthog.capture('today prompt dismissed', { prompt })
            actions.dismissPromptForTeam(values.currentTeamId, prompt)
        },
    })),
])
